CREATE TRIGGER CDN.KntKartyAlias2_DeleteHandler ON CDN.KntKarty FOR DELETE AS SET NOCOUNT ON
-- obsługa sprawdzania relacji restrict do tabeli CDN.KntWzorce IF EXISTS ( SELECT * FROM CDN.KntWzorce, deleted WHERE deleted.Knt_GIDTyp = CDN.KntWzorce.KnW_KnCTyp AND deleted.Knt_GIDNumer = CDN.KntWzorce.KnW_KnCNumer AND (CDN.KntWzorce.KnW_KnCTyp=32 AND CDN.KntWzorce.KnW_KnCNumer <> 0) ) BEGIN RAISERROR('Istnieją zapisy powiązane z modyfikowanym rekordem (powiązanie z tabelą KntWzorce) [KntKartyAlias2_DeleteHandler]. ', 16, 1) ROLLBACK TRAN SET NOCOUNT OFF RETURN END -- obsługa sprawdzania relacji restrict do tabeli CDN.ImpNag IF EXISTS ( SELECT * FROM CDN.ImpNag, deleted WHERE deleted.Knt_GIDNumer = CDN.ImpNag.ImN_KnDNumer
) BEGIN RAISERROR('#CDN_BLAD/##CDN_1=Nie można usunąć kontrahenta. Kontrahent jest ustawiony jako docelowy na dokumencie importowym./# [KntKartyAlias2_DeleteHandler]', 16, 1) ROLLBACK TRAN SET NOCOUNT OFF RETURN END -- obsługa sprawdzania relacji restrict do tabeli CDN.TraNag IF EXISTS ( SELECT * FROM CDN.TraNag, deleted WHERE deleted.Knt_GIDNumer = CDN.TraNag.TrN_KnDNumer
) BEGIN RAISERROR('#CDN_BLAD/##CDN_1=Nie można usunąć kontrahenta. Kontrahent jest ustawiony jako docelowy na dokumencie handlowym./# [KntKartyAlias2_DeleteHandler]', 16, 1) ROLLBACK TRAN SET NOCOUNT OFF RETURN END -- obsługa sprawdzania relacji restrict do tabeli CDN.SadNag IF EXISTS ( SELECT * FROM CDN.SadNag, deleted WHERE deleted.Knt_GIDNumer = CDN.SadNag.SaN_AkwNumer AND (CDN.SadNag.SaN_AkwTyp=32) ) BEGIN RAISERROR('Istnieją zapisy powiązane z modyfikowanym rekordem (powiązanie z tabelą SadNag) [KntKartyAlias2_DeleteHandler]. ', 16, 1) ROLLBACK TRAN SET NOCOUNT OFF RETURN END
SET NOCOUNT OFF

