CREATE TRIGGER CDN.PrjStruktura_DeleteHandler ON CDN.PrjStruktura FOR DELETE AS SET NOCOUNT ON
-- obsługa sprawdzania relacji restrict do tabeli CDN.UmwNag IF EXISTS ( SELECT * FROM CDN.UmwNag, deleted WHERE deleted.PRJ_Id = CDN.UmwNag.UmN_PrjId
) BEGIN RAISERROR('#CDN_BLAD/##CDN_1=Usunięcie projektu nie jest możliwe. Projekt jest powiązany z dokumentem./# [PrjStruktura_DeleteHandler]', 16, 1) ROLLBACK TRAN SET NOCOUNT OFF RETURN END -- obsługa sprawdzania relacji restrict do tabeli CDN.ZamNag IF EXISTS ( SELECT * FROM CDN.ZamNag, deleted WHERE deleted.PRJ_Id = CDN.ZamNag.ZaN_PrjId
) BEGIN RAISERROR('#CDN_BLAD/##CDN_1=Usunięcie projektu nie jest możliwe. Projekt jest powiązany z dokumentem./# [PrjStruktura_DeleteHandler]', 16, 1) ROLLBACK TRAN SET NOCOUNT OFF RETURN END -- obsługa sprawdzania relacji restrict do tabeli CDN.TraNag IF EXISTS ( SELECT * FROM CDN.TraNag, deleted WHERE deleted.PRJ_Id = CDN.TraNag.TrN_PrjId ) BEGIN RAISERROR('Istnieją zapisy powiązane z modyfikowanym rekordem (powiązanie z tabelą TraNag) [PrjStruktura_DeleteHandler]. ', 16, 1) ROLLBACK TRAN SET NOCOUNT OFF RETURN END -- obsługa sprawdzania relacji restrict do tabeli CDN.ProdTechnologia IF EXISTS ( SELECT * FROM CDN.ProdTechnologia, deleted WHERE deleted.PRJ_Id = CDN.ProdTechnologia.PTE_PrjId ) BEGIN RAISERROR('Istnieją zapisy powiązane z modyfikowanym rekordem (powiązanie z tabelą ProdTechnologia) [PrjStruktura_DeleteHandler]. ', 16, 1) ROLLBACK TRAN SET NOCOUNT OFF RETURN END -- obsługa sprawdzania relacji restrict do tabeli CDN.ProdZlecenia IF EXISTS ( SELECT * FROM CDN.ProdZlecenia, deleted WHERE deleted.PRJ_Id = CDN.ProdZlecenia.PZL_Projekt ) BEGIN RAISERROR('Istnieją zapisy powiązane z modyfikowanym rekordem (powiązanie z tabelą ProdZlecenia) [PrjStruktura_DeleteHandler]. ', 16, 1) ROLLBACK TRAN SET NOCOUNT OFF RETURN END -- obsługa sprawdzania relacji restrict do tabeli CDN.BudzetPrjNag IF EXISTS ( SELECT * FROM CDN.BudzetPrjNag, deleted WHERE deleted.PRJ_Id = CDN.BudzetPrjNag.BPN_PrjId
) BEGIN RAISERROR('#CDN_BLAD/##CDN_1=Usunięcie projektu nie jest możliwe. Projekt jest powiązany z budżetem./# [PrjStruktura_DeleteHandler]', 16, 1) ROLLBACK TRAN SET NOCOUNT OFF RETURN END -- obsługa sprawdzania relacji restrict do tabeli CDN.BudzetPrjElem IF EXISTS ( SELECT * FROM CDN.BudzetPrjElem, deleted WHERE deleted.PRJ_Id = CDN.BudzetPrjElem.BPE_PrjID
) BEGIN RAISERROR('#CDN_BLAD/##CDN_1=Usunięcie projektu nie jest możliwe. Projekt jest powiązany z budżetem./# [PrjStruktura_DeleteHandler]', 16, 1) ROLLBACK TRAN SET NOCOUNT OFF RETURN END -- obsługa sprawdzania relacji restrict do tabeli CDN.SrwPlanPrzegladu IF EXISTS ( SELECT * FROM CDN.SrwPlanPrzegladu, deleted WHERE deleted.PRJ_Id = CDN.SrwPlanPrzegladu.SPP_PrjId
) BEGIN RAISERROR('#CDN_BLAD/##CDN_1=Usunięcie projektu nie jest możliwe. Projekt jest powiązany z dokumentem./# [PrjStruktura_DeleteHandler]', 16, 1) ROLLBACK TRAN SET NOCOUNT OFF RETURN END -- obsługa sprawdzania relacji restrict do tabeli CDN.SrwZlcNag IF EXISTS ( SELECT * FROM CDN.SrwZlcNag, deleted WHERE deleted.PRJ_Id = CDN.SrwZlcNag.SZN_PrjId
) BEGIN RAISERROR('#CDN_BLAD/##CDN_1=Usunięcie projektu nie jest możliwe. Projekt jest powiązany z dokumentem./# [PrjStruktura_DeleteHandler]', 16, 1) ROLLBACK TRAN SET NOCOUNT OFF RETURN END -- obsługa sprawdzania relacji restrict do tabeli CDN.ProdNadzlecenia IF EXISTS ( SELECT * FROM CDN.ProdNadzlecenia, deleted WHERE deleted.PRJ_Id = CDN.ProdNadzlecenia.PNZ_Projekt ) BEGIN RAISERROR('Istnieją zapisy powiązane z modyfikowanym rekordem (powiązanie z tabelą ProdNadzlecenia) [PrjStruktura_DeleteHandler]. ', 16, 1) ROLLBACK TRAN SET NOCOUNT OFF RETURN END
-- obsługa kaskadowego kasowania wierszy z tabeli CDN.CRMDokumentyLinki IF EXISTS(SELECT * FROM CDN.CRMDokumentyLinki, deleted WHERE deleted.PRJ_Id = CDN.CRMDokumentyLinki.CDL_DokNumer AND (CDN.CRMDokumentyLinki.CDL_DokTyp in (4592,-4592)) ) DELETE CDN.CRMDokumentyLinki FROM CDN.CRMDokumentyLinki, deleted WHERE deleted.PRJ_Id = CDN.CRMDokumentyLinki.CDL_DokNumer AND (CDN.CRMDokumentyLinki.CDL_DokTyp in (4592,-4592))
