-- obsługa kaskadowego kasowania wierszy z tabeli CDN.AtrybutyHist IF EXISTS(SELECT * FROM CDN.AtrybutyHist, deleted WHERE deleted.PRJ_Id = CDN.AtrybutyHist.AtH_ObiNumer AND ( CDN.AtrybutyHist.Ath_OBITyp= -4592 and CDN.AtrybutyHist.Ath_OBILp = 0) ) DELETE CDN.AtrybutyHist FROM CDN.AtrybutyHist, deleted WHERE deleted.PRJ_Id = CDN.AtrybutyHist.AtH_ObiNumer AND ( CDN.AtrybutyHist.Ath_OBITyp= -4592 and CDN.AtrybutyHist.Ath_OBILp = 0)
SET NOCOUNT OFF

